\begin{figure*}[t]
\centering
\footnotesize
\begin{tikzpicture}[>=Latex,
  box/.style={draw,rounded corners,align=center,font=\footnotesize,
    inner sep=2.5pt, minimum height=9mm, text width=18mm}]
\node[box] (klmm) at (0,0)      {$R<1$\\ \cite{Krajci15}};
\node[box] (rec)  at (0,-1.7)   {recursion \&\\ key lemma};
\node[box] (aff)  at (2.7,0)     {affine bound\\ (Thm~\ref{thm:aff})};
\node[box] (env)  at (4.9,1.7)   {middle envelope\\ (Thm~\ref{thm:mid})};
\node[box] (quar) at (6.9,0)     {quarter window\\ (Thm~\ref{thm:quarter})};
\node[box] (half) at (5.3,-1.7)  {$p_1{\ge}\tfrac12$ branch\\ (Cor~\ref{cor:isob})};
\node[box] (main) at (9.4,0)     {\textbf{Theorem~\ref{thm:main}}};

\draw[->] (klmm) -- (aff);
\draw[->] (aff)  -- (quar);
\draw[->] (quar) -- (main.west);

\draw[->] (rec)  -- (aff.south west);
\draw[->] (half.north) -- (quar.south west);

\draw[->] (aff.north east) -- (env.south west);
\draw[->] (env.south east) -- (quar.north west);

\draw[->] (env.east)  to[out=0,in=145] (main.north west);
\draw[->] (half.east) to[out=0,in=215] (main.south west);
\end{tikzpicture}
\caption{Logical dependency of the results. The KLMM bound starts an affine
induction; substituting it back through the recursion gives the middle envelope
and the cap $R<K$; a further substitution below $\tfrac13$ gives the
quarter-window ceiling; the pieces combine into Theorem~\ref{thm:main}.}
\label{fig:dep}
\end{figure*}

